-- Solo PostgreSQL local descartable: fixtures parciales, NO esquema administrado real de Supabase.
-- No ejecutar remoto. Sin usuarios, secretos, Vault real, pg_net, HTTP ni servicios de Auth/Storage/Realtime.
-- Las migraciones Venus 0001-0036 se ejecutan sin quitar ni sustituir sentencias.
-- Referencias de contratos: https://github.com/supabase/postgres/blob/develop/migrations/db/init-scripts/00000000000000-initial-schema.sql
-- https://supabase.com/docs/guides/storage/schema/helper-functions
BEGIN;
DO $guard$
begin
  if current_database() <> 'venus_sql_test' or inet_server_addr() is null
     or not inet_server_addr() <<= '127.0.0.0/8'::inet then
    raise exception 'Solo venus_sql_test en loopback IPv4 local, sin túneles';
  end if;
  if exists (select 1 from pg_namespace where nspname in ('auth','storage','realtime','vault','net'))
     or exists (select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace
                  where n.nspname='public' and c.relkind in ('r','p','v','m')) then
    raise exception 'Los fixtures requieren una base nueva y vacía';
  end if;
end $guard$;

CREATE ROLE anon NOLOGIN NOINHERIT;
CREATE ROLE authenticated NOLOGIN NOINHERIT;
CREATE ROLE service_role NOLOGIN NOINHERIT BYPASSRLS;
CREATE SCHEMA extensions;
CREATE SCHEMA auth;
CREATE SCHEMA storage;
CREATE SCHEMA realtime;
-- Vault vacío solo para compilar private.payments_secret de 0017: no cifrado, valores ni API.
CREATE SCHEMA vault;
CREATE TABLE vault.secrets (id uuid PRIMARY KEY, name text CHECK (false));
CREATE VIEW vault.decrypted_secrets AS SELECT id, name, NULL::text AS decrypted_secret FROM vault.secrets;
CREATE EXTENSION pgcrypto WITH SCHEMA extensions;
GRANT USAGE ON SCHEMA public, extensions, auth, storage, realtime TO anon, authenticated, service_role;
-- Defaults históricos del esquema público de Supabase; las migraciones deben revocar lo que no exponen.
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON SEQUENCES TO anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON FUNCTIONS TO anon, authenticated, service_role;

CREATE TABLE auth.users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), aud text, role text, email text,
  email_confirmed_at timestamptz, raw_app_meta_data jsonb, raw_user_meta_data jsonb,
  banned_until timestamptz, deleted_at timestamptz, last_sign_in_at timestamptz,
  created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), is_anonymous boolean DEFAULT false
);
CREATE TABLE auth.sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id));
CREATE TABLE auth.refresh_tokens (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id text, revoked boolean);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE SET search_path = '' AS $$
  select coalesce(nullif(current_setting('request.jwt.claim.sub', true), ''),
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')::uuid
$$;
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql STABLE SET search_path = '' AS $$
  select coalesce(nullif(current_setting('request.jwt.claim', true), ''),
                  nullif(current_setting('request.jwt.claims', true), ''))::jsonb
$$;

CREATE TABLE storage.buckets (
  id text PRIMARY KEY, name text NOT NULL UNIQUE, owner uuid, public boolean DEFAULT false,
  file_size_limit bigint, allowed_mime_types text[], created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now()
);
CREATE TABLE storage.objects (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), bucket_id text REFERENCES storage.buckets(id), name text,
  owner uuid, owner_id text, metadata jsonb, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(),
  last_accessed_at timestamptz DEFAULT now(), UNIQUE(bucket_id, name)
);
ALTER TABLE storage.buckets ENABLE ROW LEVEL SECURITY;
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
GRANT ALL ON storage.buckets, storage.objects TO anon, authenticated, service_role;
CREATE FUNCTION storage.foldername(name text) RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path = '' AS $$
  select parts[1:cardinality(parts)-1] from (select string_to_array(name, '/') as parts) p
$$;
CREATE FUNCTION storage.filename(name text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path = '' AS $$
  select parts[cardinality(parts)] from (select string_to_array(name, '/') as parts) p
$$;
CREATE FUNCTION storage.extension(name text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path = '' AS $$
  select reverse(split_part(reverse(storage.filename(name)), '.', 1))
$$;

CREATE TABLE realtime.messages (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, topic text, extension text NOT NULL,
  payload jsonb, event text, private boolean DEFAULT false, inserted_at timestamptz DEFAULT now()
);
ALTER TABLE realtime.messages ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT ON realtime.messages TO anon, authenticated, service_role;
CREATE FUNCTION realtime.topic() RETURNS text LANGUAGE sql STABLE SET search_path = '' AS $$
  select nullif(current_setting('realtime.topic', true), '')
$$;
-- No entrega mensajes: si se invoca antes de la barrera del harness, aborta.
CREATE FUNCTION realtime.send(payload jsonb, event text, topic text, private boolean DEFAULT true)
RETURNS void LANGUAGE plpgsql SET search_path = '' AS $$
begin raise exception 'Fixture Realtime: ejecutar solo dentro del harness que sustituye send'; end
$$;
CREATE PUBLICATION supabase_realtime;
COMMIT;
